/* Shared plumbing for every page: data loading, formatting, tables, theme.
 *
 *   index.html    landing: landmarks and the [[n,k,d]] table   data/index.json
 *   search.html   every factory, filtered and sorted           data/index.json
 *   params.html   the gates at one [[n,k,d]]                    data/index.json
 *   factory.html  one circuit's matrix                          data/factories/<id>.json
 *
 * Both data files are generated by website/build_site.py from
 * master_catalog/master_catalog.json.  The index is fetched once and cached in
 * memory; the per-circuit files are fetched one at a time, which is why
 * `columns` is not in the index.
 */
(function (global) {
  "use strict";

  /* Pages live at the site root and two levels down (f/<label>/, p/<n.k.d>/);
   * the build writes how far up the root is, and every link is made from it. */
  var rootMeta = document.querySelector('meta[name="site-root"]');
  var ROOT = rootMeta ? rootMeta.getAttribute("content") : "./";
  var DATA = ROOT + "data/";
  var REPO = "https://github.com/shubhamj810/magic-state-factory-repo";
  var CATALOG_FILE = REPO + "/blob/main/master_catalog/master_catalog.json";
  var CATALOG_RAW = "https://raw.githubusercontent.com/shubhamj810/magic-state-factory-repo/main/master_catalog/master_catalog.json";
  var indexPromise = null;

  function loadIndex() {
    if (!indexPromise) {
      indexPromise = fetch(DATA + "index.json").then(function (response) {
        if (!response.ok) throw new Error("data/index.json: HTTP " + response.status);
        return response.json();
      });
    }
    return indexPromise;
  }

  var ID_RE = /^\d+\.\d+\.\d+\.[a-z]+$/;           /* a catalog label, n.k.d.x */

  function loadFactory(id) {
    if (!ID_RE.test(id)) return Promise.reject(new Error("not a factory id: " + id));
    return fetch(DATA + "factories/" + id + ".json").then(function (response) {
      if (!response.ok) throw new Error("no factory " + id + " (HTTP " + response.status + ")");
      return response.json();
    });
  }

  /* ------------------------------------------------------------ formatting */
  function blank(value) {
    return value === null || value === undefined || (typeof value === "number" && Number.isNaN(value));
  }

  function num(value, places) {
    return blank(value) ? "—" : Number(value).toFixed(places === undefined ? 3 : places);
  }

  function integer(value) {
    return blank(value) ? "—" : String(value);
  }

  /* A gate, escaped, that may wrap between its terms but never inside one. */
  function gateHtml(text) {
    return escapeHtml(text).replace(/·/g, "·<wbr>");
  }

  function params(n, k, d) {
    return "[[" + n + ", " + k + ", " + d + "]]";
  }

  /* ----------------------------------------------------------------- maths */
  /* Every symbol on the site is typeset by KaTeX, so it reads like the papers
   * it comes from; if KaTeX failed to load, the TeX source is shown instead. */
  var TEX = {
    gr: "\\gamma_\\rho", g: "\\gamma", gt: "\\gamma_T", vex: "V_{\\mathrm{ex}}",
    pure: "T^{\\otimes k}",
    grDef: "\\gamma_\\rho = \\log(n/V_{\\mathrm{ex}})/\\log d",
    gDef: "\\gamma = \\log(n/k)/\\log d",
    gtDef: "\\gamma_T = \\log(n/T)/\\log d"
  };

  function tex(source) {
    if (global.katex) {
      try { return global.katex.renderToString(String(source), { throwOnError: false }); } catch (e) { /* fall through */ }
    }
    return '<span class="tex-fallback">' + escapeHtml(source) + "</span>";
  }

  function paramsTex(n, k, d) {
    return tex("[\\![" + n + ",\\," + k + ",\\," + d + "]\\!]");
  }

  /* "T0·CS01·CCZ012" -> T_0 . CS_{01} . CCZ_{012}, breakable after each dot */
  function gateTex(human) {
    var text = String(human || ""), more = /\.\.\.$/.test(text);
    if (more) text = text.slice(0, -3);
    var terms = text.split("·").filter(Boolean).map(function (tok) {
      var m = /^(CCZ|CS|T)(.*)$/.exec(tok);
      return m ? "\\mathrm{" + m[1] + "}_{" + m[2] + "}" : "\\mathrm{" + tok.replace(/[^A-Za-z0-9,]/g, "") + "}";
    });
    return tex(terms.join("\\cdot ") + (more ? "\\cdots" : ""));
  }

  function renderTex(root) {
    (root || document).querySelectorAll(".tex:not([data-tex])").forEach(function (el) {
      el.setAttribute("data-tex", el.textContent);
      el.innerHTML = tex(el.textContent);
    });
  }

  function paramsHref(n, k, d) {
    return ROOT + "p/" + n + "." + k + "." + d + "/";
  }

  function factoryHref(label) {
    return ROOT + "f/" + label + "/";
  }

  function url(path) {
    return ROOT + path;
  }

  function escapeHtml(text) {
    return String(text === null || text === undefined ? "" : text)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function query(name) {
    return new URLSearchParams(global.location.search).get(name);
  }

  /* The re-verified distance, and beside it any larger distance a source certified. */
  function distanceTag(row) {
    var verified = row.d_is_exact
      ? '<span class="tag exact" title="verified here: exact">d = ' + row.d + "</span>"
      : '<span class="tag floor" title="verified here: a proved lower bound">d &ge; ' + row.d + "</span>";
    if (row.d_cert && row.d_cert > row.d) {
      /* a certified lower bound that a fault exhibited here meets is the distance */
      verified += row.d_cert_met && !row.d_cert_exact
        ? ' <span class="tag cert" title="its source certifies d &ge; ' + row.d_cert +
          ", and a damaging fault of weight " + row.d_cert + " is exhibited here, so d = " +
          row.d_cert + '">certified ' + row.d_cert + "</span>"
        : ' <span class="tag cert" title="certified by its source, not re-checked here">certified ' +
          (row.d_cert_exact ? "" : "&ge; ") + row.d_cert + "</span>";
    }
    return verified;
  }

  /* A value computed at a source-certified distance carries a dagger. */
  function claimMark(row) {
    var dc = row.d_claim, dv = row.d;
    return dc && dc > dv ? '<sup class="cert-mark" title="at the distance certified by its source, d = ' +
      dc + '">&dagger;</sup>' : "";
  }

  /* One citation from the catalogue's reference table, linked when it can be. */
  function referenceHtml(ref) {
    var full = escapeHtml(ref.full || ref.short || ref.key);
    if (ref.url) full += ' <a href="' + escapeHtml(ref.url) + '" rel="noopener">' +
                         escapeHtml(ref.url.replace(/^https?:\/\/(dx\.)?/, "")) + "</a>";
    return full;
  }

  function referenceShort(index, key) {
    var ref = (index.references || {})[key];
    return ref ? (ref.short || key) : key;
  }

  function fail(container, error) {
    container.innerHTML =
      '<div class="error"><h2>Could not load the catalogue</h2><p>' +
      escapeHtml(error && error.message ? error.message : error) + "</p>" +
      '<p class="small">The pages read JSON over <code>fetch</code>, which ' +
      "browsers refuse on <code>file://</code> URLs. Build and serve the site " +
      'instead:</p><pre class="raw">python website/build_site.py\n' +
      "python -m http.server -d website/_site 8000</pre>" +
      '<p class="small"><a href="index.html">Back to the catalogue</a></p></div>';
    if (global.console) console.error(error);
  }

  /* Save text as a file the browser downloads. */
  function download(filename, text, mime) {
    var blob = new Blob([text], { type: mime || "text/plain" });
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    setTimeout(function () { URL.revokeObjectURL(url); a.remove(); }, 0);
  }

  function csvCell(value) {
    if (blank(value)) return "";
    if (Array.isArray(value)) value = value.join("; ");
    var text = String(value);
    return /[",\n]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
  }

  function toCsv(rows, fields) {
    return fields.join(",") + "\n" + rows.map(function (row) {
      return fields.map(function (f) { return csvCell(row[f]); }).join(",");
    }).join("\n") + "\n";
  }

  /* Copy, with a fallback for browsers that refuse the async clipboard. */
  function copy(text, button) {
    function done(ok) {
      if (!button) return;
      var original = button.getAttribute("data-label") || button.textContent;
      button.setAttribute("data-label", original);
      button.textContent = ok ? "copied" : "copy failed";
      setTimeout(function () { button.textContent = original; }, 1400);
    }
    if (navigator.clipboard && global.isSecureContext) {
      navigator.clipboard.writeText(text).then(function () { done(true); },
                                               function () { done(false); });
      return;
    }
    var area = document.createElement("textarea");
    area.value = text;
    area.setAttribute("readonly", "");
    area.style.position = "fixed";
    area.style.opacity = "0";
    document.body.appendChild(area);
    area.select();
    var ok = false;
    try { ok = document.execCommand("copy"); } catch (e) { ok = false; }
    area.remove();
    done(ok);
  }

  /* ---------------------------------------------------------------- theme */
  function initTheme() {
    var stored = null;
    try { stored = localStorage.getItem("msfc-theme"); } catch (e) { /* private mode */ }
    if (stored === "dark" || stored === "light") {
      document.documentElement.setAttribute("data-theme", stored);
    }
    var button = document.getElementById("theme-toggle");
    if (!button) return;
    var SUN = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></svg>';
    var MOON = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 14.5A8 8 0 0 1 9.5 4a8 8 0 1 0 10.5 10.5z"/></svg>';
    function label() {
      var explicit = document.documentElement.getAttribute("data-theme");
      var dark = explicit ? explicit === "dark"
                          : global.matchMedia && global.matchMedia("(prefers-color-scheme: dark)").matches;
      button.innerHTML = dark ? SUN : MOON;
      button.setAttribute("aria-label", "switch to " + (dark ? "light" : "dark") + " theme");
      button.title = "switch to " + (dark ? "light" : "dark") + " theme";
    }
    label();
    button.addEventListener("click", function () {
      var root = document.documentElement;
      var explicit = root.getAttribute("data-theme");
      var dark = explicit ? explicit === "dark"
                          : global.matchMedia && global.matchMedia("(prefers-color-scheme: dark)").matches;
      var next = dark ? "light" : "dark";
      root.setAttribute("data-theme", next);
      try { localStorage.setItem("msfc-theme", next); } catch (e) { /* ignore */ }
      label();
    });
  }

  /* ------------------------------------------------- sortable table helper */
  /* Attaches click-to-sort to a <thead> whose <th> carry data-key and
   * data-type ("number" | "text").  `render` is called with the sorted rows.
   * `onSort` (optional) hears every change, so a page can keep it in the URL. */
  function compare(a, b, key, type) {
    var left = a[key], right = b[key];
    if (type === "number") {
      if (blank(left) && blank(right)) return 0;
      if (blank(left)) return 1;                      /* blanks last, either way */
      if (blank(right)) return -1;
      return left - right;
    }
    return String(blank(left) ? "" : left)
      .localeCompare(String(blank(right) ? "" : right), undefined, { numeric: true });
  }

  function sortRows(rows, key, type, direction) {
    return rows.slice().sort(function (a, b) {
      var c = compare(a, b, key, type);
      /* keep blanks last in both directions */
      if (type === "number" && (blank(a[key]) || blank(b[key]))) return c;
      return c * direction;
    });
  }

  function sortable(table, getRows, render, initial, onSort) {
    var state = initial || { key: null, direction: 1 };
    if (typeof getRows !== "function") {
      var fixed = getRows;
      getRows = function () { return fixed; };
    }

    function apply() {
      var rows = getRows();
      var sorted = rows;
      if (state.key) {
        var header = table.querySelector('th[data-key="' + state.key + '"]');
        var type = header ? header.getAttribute("data-type") : "number";
        sorted = sortRows(rows, state.key, type, state.direction);
      }
      table.querySelectorAll("th[data-key]").forEach(function (th) {
        var on = th.getAttribute("data-key") === state.key;
        th.setAttribute("aria-sort", on ? (state.direction > 0 ? "ascending" : "descending") : "none");
        th.querySelector(".arrow").textContent = on ? (state.direction > 0 ? "↑" : "↓") : "↕";
      });
      render(sorted);
    }

    table.querySelectorAll("th[data-key]").forEach(function (th) {
      if (!th.querySelector(".arrow")) {
        var arrow = document.createElement("span");
        arrow.className = "arrow";
        arrow.setAttribute("aria-hidden", "true");
        arrow.textContent = "↕";
        th.appendChild(arrow);
      }
      th.tabIndex = 0;
      function choose() {
        var key = th.getAttribute("data-key");
        state = (state.key === key) ? { key: key, direction: -state.direction }
                                    : { key: key, direction: 1 };
        if (onSort) onSort(state);
        apply();
      }
      th.addEventListener("click", choose);
      th.addEventListener("keydown", function (event) {
        if (event.key === "Enter" || event.key === " ") { event.preventDefault(); choose(); }
      });
    });
    apply();
    return {
      refresh: apply,
      state: function () { return state; },
      set: function (next) { state = next; apply(); }
    };
  }

  /* A circuit as a grid of cells: output rows, check rows, zeros. */
  function matrixSvg(record, cell) {
    var p = record.parameters, n = p.n, N = p.N, k = p.k, gap = Math.max(1, Math.round(cell / 7));
    var on = [];
    for (var q = 0; q < N; q++) on.push(new Uint8Array(n));
    record.circuit.columns.forEach(function (col, j) {
      col.forEach(function (w) { if (w < N) on[w][j] = 1; });
    });
    var step = cell + gap, W = n * step - gap, H = N * step - gap, parts = [];
    for (q = 0; q < N; q++) {
      for (var j = 0; j < n; j++) {
        parts.push('<rect class="' + (on[q][j] ? (q < k ? "cell-out" : "cell-chk") : "cell-zero") +
                   '" x="' + j * step + '" y="' + q * step + '" width="' + cell + '" height="' + cell + '"/>');
      }
    }
    return '<svg class="mini-matrix" viewBox="0 0 ' + W + " " + H + '" width="' + W + '" role="img" aria-label="' +
           N + " by " + n + ' binary matrix">' + parts.join("") + "</svg>";
  }

  /* Rows that open a link when clicked anywhere, not only on the anchor. */
  function clickableRows(body) {
    body.addEventListener("click", function (event) {
      if (event.target.closest("a, button, input, label")) return;
      var tr = event.target.closest("tr[data-href]");
      if (!tr) return;
      if (event.metaKey || event.ctrlKey) global.open(tr.getAttribute("data-href"), "_blank");
      else global.location.href = tr.getAttribute("data-href");
    });
  }

  /* "‹ prev  1 2 3 … 17  next ›" -- returns HTML; buttons carry data-page. */
  function pagerHtml(page, pages) {
    if (pages <= 1) return "";
    var items = [], last = -1;
    for (var p = 1; p <= pages; p++) {
      if (p === 1 || p === pages || Math.abs(p - page) <= 2) {
        if (last !== -1 && p - last > 1) items.push('<span class="gap">…</span>');
        items.push('<button type="button" data-page="' + p + '"' +
                   (p === page ? ' aria-current="page" class="on"' : "") + ">" + p + "</button>");
        last = p;
      }
    }
    return '<nav class="pager" aria-label="pages">' +
      '<button type="button" data-page="' + (page - 1) + '"' + (page <= 1 ? " disabled" : "") +
      ">‹ prev</button>" + items.join("") +
      '<button type="button" data-page="' + (page + 1) + '"' + (page >= pages ? " disabled" : "") +
      ">next ›</button></nav>";
  }

  global.Catalog = {
    DATA: DATA, REPO: REPO, CATALOG_FILE: CATALOG_FILE, CATALOG_RAW: CATALOG_RAW,
    loadIndex: loadIndex,
    loadFactory: loadFactory,
    blank: blank,
    num: num,
    integer: integer,
    params: params,
    TEX: TEX,
    tex: tex,
    paramsTex: paramsTex,
    gateTex: gateTex,
    matrixSvg: matrixSvg,
    renderTex: renderTex,
    paramsHref: paramsHref,
    url: url,
    ROOT: ROOT,
    factoryHref: factoryHref,
    escapeHtml: escapeHtml,
    gateHtml: gateHtml,
    query: query,
    distanceTag: distanceTag,
    claimMark: claimMark,
    referenceHtml: referenceHtml,
    referenceShort: referenceShort,
    fail: fail,
    download: download,
    toCsv: toCsv,
    copy: copy,
    initTheme: initTheme,
    sortRows: sortRows,
    sortable: sortable,
    clickableRows: clickableRows,
    pagerHtml: pagerHtml
  };

  document.addEventListener("DOMContentLoaded", function () {
    initTheme();
    renderTex(document);
    /* "/" jumps to the search box, as on most data sites */
    document.addEventListener("keydown", function (event) {
      if (event.key !== "/" || event.metaKey || event.ctrlKey || event.altKey) return;
      var t = event.target;
      if (t && (t.isContentEditable || /^(input|textarea|select)$/i.test(t.tagName))) return;
      var box = document.getElementById("q") || document.getElementById("hero-q") || document.getElementById("nav-q");
      if (box) { event.preventDefault(); box.focus(); box.select(); }
    });
    /* The footer's data stamp is written by build_site.py, so no page
     * downloads the index just to print a commit hash. */
  });
}(window));
